<?php
namespace Tests\Feature; use App\Models\User; use App\Models\Wedding; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class EventCreateTest extends TestCase { use RefreshDatabase; public function test_admin_can_create_primary_event_with_utc_start(): void { $admin=User::factory()->create(['role'=>'admin']); $wedding=Wedding::create(['name'=>'Evento','slug'=>'evento','timezone'=>'America/Mexico_City']); $this->actingAs($admin)->post(route('weddings.events.store',$wedding),['name'=>'Ceremonia','type'=>'ceremony','event_date'=>'2027-05-20','event_time'=>'18:00','is_primary'=>true])->assertRedirect(route('weddings.show',$wedding)); $this->assertDatabaseHas('wedding_events',['wedding_id'=>$wedding->id,'name'=>'Ceremonia','is_primary'=>1]); } public function test_assigned_coordinator_can_open_the_event_form_without_a_membership(): void { $coordinator=User::factory()->create(['role'=>'coordinator']); $wedding=Wedding::create(['name'=>'Evento coordinado','slug'=>'evento-coordinado','timezone'=>'America/Mexico_City','coordinator_id'=>$coordinator->id]); $this->actingAs($coordinator)->get(route('weddings.events.create',$wedding))->assertOk()->assertInertia(fn ($page) => $page->component('Weddings/EventCreate')); } }
